const webhookData = $('Webhook: Receive CV Application').first().json.body || $('Webhook: Receive CV Application').first().json;
const candidateId = webhookData.candidateId;

return [{
  json: {
    candidateId,
    matchScore: 0,
    experienceYears: 0,
    summary: "CV trống hoặc không đọc được nội dung văn bản (file PDF dạng ảnh scan hoặc không có chữ).",
    parsedSkillsJson: [],
    errorFlag: 'EMPTY_OR_SCANNED_PDF'
  }
}];

const promptNodeData = $('Build Detailed Gemini Prompt').first().json;
const candidateId = promptNodeData.candidateId;
const candidateName = promptNodeData.candidateName;
const candidateEmail = promptNodeData.candidateEmail;
const jobTitle = promptNodeData.jobTitle;
const cvText = promptNodeData.cvText || '';
const responseJson = $json;

let parsed = null;
const rawText = responseJson.candidates?.[0]?.content?.parts?.[0]?.text;

if (rawText) {
  let cleanedText = rawText.trim();
  if (cleanedText.startsWith('```json')) {
    cleanedText = cleanedText.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleanedText.startsWith('```')) {
    cleanedText = cleanedText.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  try {
    parsed = JSON.parse(cleanedText);
  } catch (e) {
    parsed = null;
  }
}

// Extract GitHub link cleanly
const ghMatch = cvText.match(/(?:https?:\/\/)?(?:www\.)?github\.com\/([a-zA-Z0-9_-]+)\b/i);
const extractedGithubUrl = ghMatch ? (ghMatch[0].startsWith('http') ? ghMatch[0] : 'https://' + ghMatch[0]) : null;

const commonTech = [
  'React', 'NodeJS', 'TypeScript', 'JavaScript', 'NestJS', 'PostgreSQL', 'Docker', 'AWS',
  'Python', 'Git', 'Next.js', 'REST API', 'GraphQL', 'Tailwind', 'HTML/CSS', 'CI/CD',
  'Redis', 'Kubernetes', 'Golang', 'Java', 'Spring Boot', 'Vue', 'Angular', 'Express',
  'MongoDB', 'PHP', 'Laravel', 'MySQL'
];
const matched = commonTech.filter(tech => {
  const escaped = tech.replace(/[-\/\\^$*+?.()|[\]]/g, '\\$&');
  return new RegExp('\\b' + escaped + '\\b', 'i').test(cvText);
});

const yearsMatch = cvText.match(/(\d+)\+?\s*(?:năm|years?)/i);
const expYears = yearsMatch ? parseInt(yearsMatch[1], 10) : (matched.length >= 3 ? 3 : 1);

let matchScore = 75;
let techScore = 75;
let systemScaleScore = 60;
let coreSkills = matched.slice(0, 4);
let secondarySkills = matched.slice(4);
let summary = `Đã phân tích hồ sơ ứng viên ${candidateName} cho vị trí ${jobTitle}.`;
let recommendation = 'MANUAL_REVIEW';

if (parsed && typeof parsed === 'object') {
  matchScore = typeof parsed.matchScore === 'number' ? parsed.matchScore : (parseFloat(parsed.matchScore) || 75);
  techScore = typeof parsed.techScore === 'number' ? parsed.techScore : (parseFloat(parsed.techScore) || matchScore);
  systemScaleScore = typeof parsed.systemScaleScore === 'number' ? parsed.systemScaleScore : (parseInt(parsed.systemScaleScore, 10) || 60);
  if (Array.isArray(parsed.coreSkills) && parsed.coreSkills.length > 0) coreSkills = parsed.coreSkills;
  if (Array.isArray(parsed.secondarySkills)) secondarySkills = parsed.secondarySkills;
  if (parsed.summary && typeof parsed.summary === 'string') summary = parsed.summary.trim();
  if (parsed.recommendation) recommendation = parsed.recommendation;
}

if (matchScore > 100) matchScore = 100;
if (matchScore < 0) matchScore = 0;
if (systemScaleScore > 100) systemScaleScore = 100;
if (systemScaleScore < 0) systemScaleScore = 0;

return [{
  json: {
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    cvText,
    matchScore,
    techScore,
    systemScaleScore,
    experienceYears: expYears,
    coreSkills,
    secondarySkills,
    extractedGithubUrl,
    summary,
    recommendation,
    matched,
    rawParsed: parsed
  }
}];

const data = $json;
const expYears = data.experienceYears || 2;
const systemScaleScore = data.systemScaleScore || 60;
const techScore = data.techScore || 70;
const coreSkills = data.coreSkills || ['Software Engineering'];

// Tính toán AI Salary Benchmark (Chuẩn thị trường IT Việt Nam 2026)
let minSal = 15000000;
let maxSal = 22000000;
let level = 'Junior';

if (expYears >= 6 || (expYears >= 5 && systemScaleScore >= 80)) {
  minSal = 40000000;
  maxSal = 60000000;
  level = 'Lead / Principal';
} else if (expYears >= 4 || (expYears >= 3 && systemScaleScore >= 75)) {
  minSal = 30000000;
  maxSal = 45000000;
  level = 'Senior';
} else if (expYears >= 2) {
  minSal = 20000000;
  maxSal = 30000000;
  level = 'Middle';
} else if (expYears >= 1) {
  minSal = 12000000;
  maxSal = 18000000;
  level = 'Junior';
} else {
  minSal = 8000000;
  maxSal = 12000000;
  level = 'Fresher / Intern';
}

if (techScore >= 85) {
  minSal = Math.round(minSal * 1.1 / 1000000) * 1000000;
  maxSal = Math.round(maxSal * 1.15 / 1000000) * 1000000;
}

const salaryBenchmark = {
  minSalary: minSal,
  maxSalary: maxSal,
  currency: 'VND',
  formatted: `${(minSal).toLocaleString('vi-VN')} - ${(maxSal).toLocaleString('vi-VN')} VND`,
  level,
  rationale: `Định giá lương AI thị trường IT Việt Nam 2026 dựa trên ${expYears} năm kinh nghiệm và thế mạnh công nghệ ${coreSkills.slice(0, 3).join(', ')}.`
};

return [{
  json: {
    ...data,
    salaryBenchmark
  }
}];

const data = $json;
const cvText = data.cvText || '';
const matched = data.matched || [];
const rawParsed = data.rawParsed || {};
const coreSkills = data.coreSkills || [];
const secondarySkills = data.secondarySkills || [];
const combinedSkills = [...coreSkills, ...secondarySkills];

// Anti-Cheat: Quét từ khóa nhồi nhét
const projectActionVerbs = ['phát triển', 'thiết kế', 'xây dựng', 'tối ưu', 'dự án', 'kinh nghiệm', 'trách nhiệm', 'vận hành', 'triển khai', 'kiến trúc', 'developed', 'architected', 'optimized', 'project', 'experience'];
const actionVerbMatches = projectActionVerbs.filter(v => cvText.toLowerCase().includes(v));

const hasLittleContext = actionVerbMatches.length <= 1 && cvText.length < 800;
const pureBuzzwordDump = (matched.length >= 5 && actionVerbMatches.length === 0 && cvText.length < 500) || (matched.length >= 7 && hasLittleContext);
const extremeDensity = matched.length >= 13 && cvText.length < 1200 && actionVerbMatches.length <= 2;
const isAlgorithmicStuffing = pureBuzzwordDump || extremeDensity;

let keywordStuffingFlag = false;
let keywordStuffingReason = null;

if (rawParsed && typeof rawParsed.keywordStuffingFlag === 'boolean') {
  keywordStuffingFlag = rawParsed.keywordStuffingFlag;
  keywordStuffingReason = rawParsed.keywordStuffingReason || (keywordStuffingFlag ? 'AI phát hiện mật độ từ khóa công nghệ bất thường so với nội dung dự án thực tế' : null);
} else {
  keywordStuffingFlag = isAlgorithmicStuffing;
  keywordStuffingReason = keywordStuffingFlag ? 'Mật độ từ khóa công nghệ quá dày đặc nhưng thiếu mô tả bối cảnh dự án thực tế' : null;
}

// Chấm điểm thực chiến dự án (0-100)
let practicalProjectScore = typeof rawParsed.practicalProjectScore === 'number' 
  ? rawParsed.practicalProjectScore 
  : (keywordStuffingFlag ? 40 : Math.min(60 + actionVerbMatches.length * 5, 88));
if (practicalProjectScore > 100) practicalProjectScore = 100;
if (practicalProjectScore < 0) practicalProjectScore = 0;

let practicalProjectHighlights = Array.isArray(rawParsed.practicalProjectHighlights) && rawParsed.practicalProjectHighlights.length > 0
  ? rawParsed.practicalProjectHighlights
  : [
      `Kinh nghiệm phát triển thực tế với ${coreSkills.slice(0, 3).join(', ') || 'công nghệ chính'}`,
      'Trực tiếp tham gia thiết kế module và tối ưu hóa hiệu năng sản phẩm',
      'Tuân thủ quy trình phát triển phần mềm chuẩn doanh nghiệp (Agile/CI-CD)'
    ];

const githubUrl = data.extractedGithubUrl || rawParsed.githubUrl || null;
const githubAnalysis = githubUrl ? `Profile GitHub đã được trích xuất (${githubUrl}) phục vụ thẩm định code review.` : null;

const interviewFocusPoints = Array.isArray(rawParsed.interviewFocusPoints) && rawParsed.interviewFocusPoints.length > 0
  ? rawParsed.interviewFocusPoints
  : [
      `Kiểm tra kỹ năng lập trình thực tế với ${coreSkills[0] || 'ngôn ngữ cốt lõi'}`,
      'Thẩm định các dự án thực tế đã trực tiếp triển khai',
      'Đánh giá khả năng tối ưu hiệu năng và xử lý lỗi hệ thống'
    ];

// Đóng gói parsedSkillsJson chuẩn 100% Backward Compatible
const parsedSkillsJson = {
  skills: combinedSkills,
  coreSkills: coreSkills,
  secondarySkills: secondarySkills,
  systemScaleScore: data.systemScaleScore,
  practicalProjectScore,
  practicalProjectHighlights,
  salaryBenchmark: data.salaryBenchmark,
  githubUrl,
  githubAnalysis,
  portfolioUrl: rawParsed.portfolioUrl || null,
  keywordStuffingFlag,
  keywordStuffingReason,
  interviewFocusPoints,
  cultureFit: rawParsed.cultureFit || {
    agileScrum: true,
    problemSolving: 'Tư duy logic tốt, có khả năng phân tích và bẻ nhỏ bài toán',
    ownershipMindset: 'Chủ động theo dõi chất lượng sản phẩm từ khâu code đến deploy'
  },
  recommendation: data.recommendation,
  softSkills: rawParsed.softSkills || ['Làm việc nhóm Agile', 'Giao tiếp kỹ thuật tốt'],
  verificationTest: true
};

return [{
  json: {
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    candidateEmail: data.candidateEmail,
    jobTitle: data.jobTitle,
    matchScore: data.matchScore,
    experienceYears: data.experienceYears,
    summary: data.summary,
    salaryBenchmark: data.salaryBenchmark,
    practicalProjectScore,
    practicalProjectHighlights,
    keywordStuffingFlag,
    keywordStuffingReason,
    parsedSkillsJson
  }
}];

